"use client";

import Link from "next/link";
import { FormEvent, type ReactNode, useEffect, useMemo, useState } from "react";
import type { ExpenseCategory, GarageCollection, GarageRepairEstimate, IssueSeverity, IssueStatus, ModificationCategory, Vehicle, VehicleExpense, VehicleIssue, VehicleMaintenanceItem, VehicleModification, VehicleReminder, VehicleServiceRecord, VehicleStatus, VehicleType, VehicleVinSpecifications } from "@/core/contracts/Garage";
import { addCalendarMonths, localDateValue, reminderStatus, useGarage } from "@/hooks/os/useGarage";
import GarageCollectionsPanel from "@/components/apps/garage/GarageCollectionsPanel";
import GarageCosmicPlusGate from "@/components/apps/garage/GarageCosmicPlusGate";
import GarageM4Experience from "@/components/apps/garage/GarageM4Experience";
import VehicleScanner from "@/components/apps/garage/VehicleScanner";
import type { VehicleScanKind } from "@/core/contracts/VehicleScanning";
import { useEntitlements } from "@/hooks/os/useEntitlements";
import { canAddActiveVehicle, countActiveVehicles, getGarageVehicleLimitState, isActiveVehicleStatus } from "@/lib/garage/limits";
import { useRouteReadiness } from "@/components/os/transition";

const tabs = ["Overview", "Mileage", "Maintenance", "Service", "Issues", "Modifications", "Expenses", "Reminders"] as const;
type Tab = typeof tabs[number];
type AddVehicleMethod = "scan" | "vin" | "plate" | "connected" | "obd2" | "manual";
type DecodedVin = VehicleVinSpecifications & { vin: string };
type DecodedPlate = { plate: string; region: string; vin?: string; specifications: Partial<VehicleVinSpecifications>; sources: string[] };
const input = "mt-1 w-full rounded-xl border border-white/15 bg-black/20 px-3 py-2 text-sm text-white outline-none focus:border-cyan-300/60";
const button = "rounded-xl bg-cyan-300/20 px-3 py-2 text-sm text-cyan-50 hover:bg-cyan-300/30 focus:outline-none focus:ring-2 focus:ring-cyan-200";
const field = (value: FormDataEntryValue | null) => typeof value === "string" ? value.trim() : "";
const optionalNumber = (value: FormDataEntryValue | null) => { const text = field(value); return text === "" ? undefined : Number(text); };
const makeId = () => crypto.randomUUID();
const money = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

export default function GarageView() {
  const garage = useGarage();
  useRouteReadiness("/garage", !garage.loading, garage.error ? "degraded" : "ready");
  const { data: entitlements } = useEntitlements();
  const [tab, setTab] = useState<Tab>("Overview");
  const [editing, setEditing] = useState<string | null>(null);
  const [collectionFilter, setCollectionFilter] = useState("all");
  const [vehicleSearch, setVehicleSearch] = useState("");
  const [classificationFilter, setClassificationFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [vehicleSort, setVehicleSort] = useState("attention");
  const [onboardingMethod, setOnboardingMethod] = useState<AddVehicleMethod>("manual");
  const [onboardingVin, setOnboardingVin] = useState("");
  const [onboardingPlate, setOnboardingPlate] = useState("");
  const [onboardingRegion, setOnboardingRegion] = useState("UT");
  const [scanKind, setScanKind] = useState<VehicleScanKind | null>(null);
  const [decodedVin, setDecodedVin] = useState<DecodedVin | null>(null);
  const [decodedPlate, setDecodedPlate] = useState<DecodedPlate | null>(null);
  const [isAddingVehicle, setIsAddingVehicle] = useState(false);
  const [showVehicleLimitGate, setShowVehicleLimitGate] = useState(false);
  const vehicle = garage.selectedVehicle;
  const summary = garage.summary;
  const vehicleLimit = getGarageVehicleLimitState(garage.data.vehicles, entitlements);
  const activeVehicleCount = countActiveVehicles(garage.data.vehicles);
  const visibleVehicles = useMemo(() => { const query = vehicleSearch.trim().toLocaleLowerCase(); return garage.data.vehicles.filter((item) => (collectionFilter === "all" || (item.collectionId ?? "my-garage") === collectionFilter) && (classificationFilter === "all" || item.classification === classificationFilter) && (statusFilter === "all" || item.status === statusFilter) && (!query || `${item.nickname} ${item.year} ${item.make} ${item.model}`.toLocaleLowerCase().includes(query))).sort((left, right) => { if (vehicleSort === "name") return left.nickname.localeCompare(right.nickname); if (vehicleSort === "mileage") return right.currentMileage - left.currentMileage; if (vehicleSort === "year") return right.year - left.year; if (vehicleSort === "updated") return right.updatedAt.localeCompare(left.updatedAt); if (vehicleSort === "primary") return Number(Boolean(right.isPrimary)) - Number(Boolean(left.isPrimary)); return Number(Boolean(right.isPrimary)) - Number(Boolean(left.isPrimary)); }); }, [classificationFilter, collectionFilter, garage.data.vehicles, statusFilter, vehicleSearch, vehicleSort]);
  const attention = useMemo(() => !vehicle || !summary ? [] : [
    ...summary.maintenance.filter((item) => ["overdue", "dueSoon"].includes(summary.statusById.get(item.id) ?? "")),
    ...summary.issues.filter((item) => item.status !== "resolved"),
    ...summary.reminders.filter((item) => ["overdue", "dueSoon"].includes(reminderStatus(item, vehicle.currentMileage))),
  ], [summary, vehicle]);
  useEffect(() => { if (!garage.loading && garage.data.vehicles.length && !garage.selectedVehicle && !isAddingVehicle) garage.selectVehicle(garage.data.vehicles[0].id); }, [garage, garage.data.vehicles, garage.loading, garage.selectedVehicle, isAddingVehicle]);
  const shouldShowVehicleLimitGate = (showVehicleLimitGate || isAddingVehicle) && !canAddActiveVehicle(garage.data.vehicles, entitlements);
  const saveVehicle = (event: FormEvent<HTMLFormElement>, existing?: Vehicle) => { event.preventDefault(); const data = new FormData(event.currentTarget); const year = Number(data.get("year")); const mileage = Number(data.get("mileage")); if (!Number.isInteger(year) || year < 1886 || year > new Date().getFullYear() + 2 || !Number.isFinite(mileage) || mileage < 0) return; if (existing && mileage < existing.currentMileage && !window.confirm("This lowers the recorded odometer. Continue only if this is a deliberate correction.")) return; const vin = normalizeVin(field(data.get("vin"))); const plate = field(data.get("plate")).toUpperCase(); const duplicate = garage.data.vehicles.find((item) => item.id !== existing?.id && ((vin && item.vin && normalizeVin(item.vin) === vin) || (plate && item.licensePlate?.toUpperCase() === plate && decodedPlate?.region))); if (duplicate && !window.confirm(`This may already be in Garage as ${duplicate.nickname}. Review the existing vehicle before creating another record.`)) return; const stamp = new Date().toISOString(); const id = existing?.id ?? makeId(); const specificationText = field(data.get("vinSpecifications")); let vinSpecifications = existing?.vinSpecifications ?? (decodedVin && decodedVin.vin === vin ? decodedVin : decodedPlate?.vin && decodedPlate.vin === vin ? { source: "nhtsa-vpic", decodedAt: stamp, ...decodedPlate.specifications } as VehicleVinSpecifications : undefined); if (specificationText) { try { vinSpecifications = JSON.parse(specificationText) as VehicleVinSpecifications; } catch { vinSpecifications = existing?.vinSpecifications; } } garage.saveVehicle({ id, nickname: field(data.get("nickname")), year, make: field(data.get("make")), model: field(data.get("model")), trim: field(data.get("trim")) || undefined, vehicleType: field(data.get("vehicleType")) as VehicleType, classification: field(data.get("classification")) as Vehicle["classification"], collectionId: field(data.get("collectionId")) || "my-garage", vin: vin || undefined, vinSpecifications, licensePlate: plate || undefined, currentMileage: mileage, status: field(data.get("status")) as VehicleStatus, isPrimary: data.get("primary") === "on", color: field(data.get("color")) || undefined, purchaseDate: field(data.get("purchaseDate")) || undefined, purchasePrice: optionalNumber(data.get("purchasePrice")), notes: field(data.get("notes")) || undefined, createdAt: existing?.createdAt ?? stamp, updatedAt: stamp }); if (!existing || existing.currentMileage !== mileage) garage.updateMileage(id, mileage, localDateValue(), "Vehicle record"); setEditing(null); setOnboardingMethod("manual"); setDecodedVin(null); setDecodedPlate(null); setOnboardingVin(""); event.currentTarget.reset(); };
  const saveMileage = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!vehicle) return; const data = new FormData(event.currentTarget); const mileage = optionalNumber(data.get("mileage")); const date = field(data.get("date")) || localDateValue(); if (mileage === undefined || mileage < 0) return; const latest = summary?.mileageHistory[0]; if (latest && mileage < latest.mileage && !window.confirm("This odometer entry is lower than the latest entry. Save it as a correction?")) return; garage.updateMileage(vehicle.id, mileage, date, field(data.get("note")) || undefined); event.currentTarget.reset(); };
  const saveMaintenance = (event: FormEvent<HTMLFormElement>, existing?: VehicleMaintenanceItem) => { event.preventDefault(); if (!vehicle) return; const data = new FormData(event.currentTarget); const intervalMiles = optionalNumber(data.get("intervalMiles")); const intervalMonths = optionalNumber(data.get("intervalMonths")); const lastMileage = optionalNumber(data.get("lastMileage")); const nextMileage = optionalNumber(data.get("nextMileage")); if ([intervalMiles, intervalMonths, lastMileage, nextMileage].some((value) => value !== undefined && (!Number.isFinite(value) || value < 0))) return; garage.saveMaintenance({ id: existing?.id ?? makeId(), vehicleId: vehicle.id, name: field(data.get("name")), intervalMiles, intervalMonths, lastServiceMileage: lastMileage, lastServiceDate: field(data.get("lastDate")) || undefined, nextDueMileage: nextMileage, nextDueDate: field(data.get("nextDate")) || undefined, priority: field(data.get("priority")) as VehicleMaintenanceItem["priority"], notes: field(data.get("notes")) || undefined, createdAt: existing?.createdAt ?? new Date().toISOString() }); setEditing(null); event.currentTarget.reset(); };
  const saveService = (event: FormEvent<HTMLFormElement>, existing?: VehicleServiceRecord) => { event.preventDefault(); if (!vehicle) return; const data = new FormData(event.currentTarget); const mileage = optionalNumber(data.get("mileage")); const cost = optionalNumber(data.get("cost")); if ((mileage !== undefined && mileage < 0) || (cost !== undefined && cost < 0)) return; garage.saveService({ id: existing?.id ?? makeId(), vehicleId: vehicle.id, title: field(data.get("title")), date: field(data.get("date")) || localDateValue(), mileage, description: field(data.get("description")) || undefined, cost, shop: field(data.get("shop")) || undefined, maintenanceItemId: field(data.get("maintenance")) || undefined, createdAt: existing?.createdAt ?? new Date().toISOString() }); setEditing(null); event.currentTarget.reset(); };
  const saveIssue = (event: FormEvent<HTMLFormElement>, existing?: VehicleIssue) => { event.preventDefault(); if (!vehicle) return; const data = new FormData(event.currentTarget); const mileage = optionalNumber(data.get("mileage")); if (mileage !== undefined && mileage < 0) return; const status = field(data.get("status")) as IssueStatus; garage.saveIssue({ id: existing?.id ?? makeId(), vehicleId: vehicle.id, title: field(data.get("title")), description: field(data.get("description")) || undefined, severity: field(data.get("severity")) as IssueSeverity, status, reportedAt: field(data.get("reportedAt")) || localDateValue(), resolvedAt: status === "resolved" ? existing?.resolvedAt ?? localDateValue() : undefined, mileage, notes: field(data.get("notes")) || undefined, createdAt: existing?.createdAt ?? new Date().toISOString() }); setEditing(null); event.currentTarget.reset(); };
  const saveModification = (event: FormEvent<HTMLFormElement>, existing?: VehicleModification) => { event.preventDefault(); if (!vehicle) return; const data = new FormData(event.currentTarget); const mileage = optionalNumber(data.get("mileage")); const cost = optionalNumber(data.get("cost")); const laborCost = optionalNumber(data.get("laborCost")); if ((mileage !== undefined && mileage < 0) || (cost !== undefined && cost < 0) || (laborCost !== undefined && laborCost < 0)) return; garage.saveModification({ id: existing?.id ?? makeId(), vehicleId: vehicle.id, name: field(data.get("name")), category: field(data.get("category")) as ModificationCategory, installedAt: field(data.get("installedAt")) || undefined, mileage, cost, laborCost, brand: field(data.get("brand")) || undefined, partNumber: field(data.get("partNumber")) || undefined, purchaseDate: field(data.get("purchaseDate")) || undefined, installer: field(data.get("installer")) || undefined, description: field(data.get("description")) || undefined, status: field(data.get("status")) || undefined, createdAt: existing?.createdAt ?? new Date().toISOString() }); setEditing(null); event.currentTarget.reset(); };
  const saveExpense = (event: FormEvent<HTMLFormElement>, existing?: VehicleExpense) => { event.preventDefault(); if (!vehicle) return; const data = new FormData(event.currentTarget); const amount = Number(data.get("amount")); const mileage = optionalNumber(data.get("mileage")); if (!Number.isFinite(amount) || amount < 0 || (mileage !== undefined && mileage < 0)) return; garage.saveExpense({ id: existing?.id ?? makeId(), vehicleId: vehicle.id, date: field(data.get("date")) || localDateValue(), category: field(data.get("category")) as ExpenseCategory, amount, description: field(data.get("description")) || undefined, mileage, createdAt: existing?.createdAt ?? new Date().toISOString() }); setEditing(null); event.currentTarget.reset(); };
  const saveReminder = (event: FormEvent<HTMLFormElement>, existing?: VehicleReminder) => { event.preventDefault(); if (!vehicle) return; const data = new FormData(event.currentTarget); const dueMileage = optionalNumber(data.get("dueMileage")); if (dueMileage !== undefined && dueMileage < 0) return; garage.saveReminder({ id: existing?.id ?? makeId(), vehicleId: vehicle.id, title: field(data.get("title")), dueDate: field(data.get("dueDate")) || undefined, dueMileage, completed: existing?.completed ?? false, createdAt: existing?.createdAt ?? new Date().toISOString() }); setEditing(null); event.currentTarget.reset(); };
  const markServiced = (item: VehicleMaintenanceItem) => { if (!vehicle) return; const serviceDate = window.prompt("Service date (YYYY-MM-DD)", localDateValue()); if (!serviceDate) return; const mileageValue = window.prompt("Service mileage", String(vehicle.currentMileage)); if (mileageValue === null || Number(mileageValue) < 0) return; const costValue = window.prompt("Cost (optional)", ""); const notes = window.prompt("Service notes (optional)", ""); const mileage = Number(mileageValue); const cost = costValue ? Number(costValue) : undefined; if (!Number.isFinite(mileage) || (cost !== undefined && (!Number.isFinite(cost) || cost < 0))) return; garage.saveService({ id: makeId(), vehicleId: vehicle.id, title: item.name, date: serviceDate, mileage, cost, description: notes || undefined, maintenanceItemId: item.id, createdAt: new Date().toISOString() }); garage.saveMaintenance({ ...item, lastServiceDate: serviceDate, lastServiceMileage: mileage, nextDueMileage: item.intervalMiles === undefined ? undefined : mileage + item.intervalMiles, nextDueDate: item.intervalMonths === undefined ? undefined : addCalendarMonths(serviceDate, item.intervalMonths) }); };
  const remove = (label: string, action: () => void) => { if (window.confirm(`Delete this ${label}? This only removes local Garage data.`)) action(); };

  const submitVehicle = (event: FormEvent<HTMLFormElement>, existing?: Vehicle) => { const status = field(new FormData(event.currentTarget).get("status")) as VehicleStatus; if (isActiveVehicleStatus(status) && !canAddActiveVehicle(garage.data.vehicles, entitlements, existing)) { setShowVehicleLimitGate(true); setIsAddingVehicle(false); return; } saveVehicle(event, existing); setIsAddingVehicle(false); };
  const openAddVehicle = () => { if (!canAddActiveVehicle(garage.data.vehicles, entitlements)) { setShowVehicleLimitGate(true); setIsAddingVehicle(false); return; } setShowVehicleLimitGate(false); setIsAddingVehicle(true); garage.selectVehicle(""); };
  const closeAddVehicle = () => { setIsAddingVehicle(false); setShowVehicleLimitGate(false); if (garage.data.vehicles.length) garage.selectVehicle(garage.selectedVehicle?.id ?? garage.data.vehicles[0].id); };
  const updateVehicleLifecycle = (status: VehicleStatus) => { if (!vehicle) return; if (isActiveVehicleStatus(status) && !canAddActiveVehicle(garage.data.vehicles, entitlements, vehicle)) { setShowVehicleLimitGate(true); return; } const sold = status === "sold"; garage.saveVehicle({ ...vehicle, status, soldDate: sold ? vehicle.soldDate ?? localDateValue() : vehicle.soldDate, updatedAt: new Date().toISOString() }); };
  if (garage.loading) return <p className="text-sm text-white/60">Loading your garage…</p>;
  return <div className="mx-auto max-w-6xl space-y-5 text-white"><header className="flex flex-wrap items-end justify-between gap-3"><div><h1 className="text-3xl font-semibold">Garage</h1><p className="mt-1 text-sm text-white/55">Local vehicle records, maintenance, and costs.</p></div><div className="flex w-full flex-wrap gap-2 lg:w-auto"><label className="sr-only" htmlFor="garage-vehicle-search">Search vehicles</label><input id="garage-vehicle-search" aria-label="Search vehicles" className="min-w-40 flex-1 rounded-xl border border-white/15 bg-slate-950/70 px-3 py-2 text-sm lg:flex-none" placeholder="Search vehicles" value={vehicleSearch} onChange={(event) => setVehicleSearch(event.target.value)} /><select aria-label="Vehicle collection" className="rounded-xl border border-white/15 bg-slate-950/70 px-3 py-2 text-sm" value={collectionFilter} onChange={(event) => setCollectionFilter(event.target.value)}><option value="all">All collections</option>{garage.data.collections.filter((item) => !item.archived).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><select aria-label="Vehicle classification" className="rounded-xl border border-white/15 bg-slate-950/70 px-3 py-2 text-sm" value={classificationFilter} onChange={(event) => setClassificationFilter(event.target.value)}><option value="all">All uses</option>{["daily", "project", "track", "work", "other"].map((item) => <option key={item} value={item}>{item}</option>)}</select><select aria-label="Vehicle status" className="rounded-xl border border-white/15 bg-slate-950/70 px-3 py-2 text-sm" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}><option value="all">All statuses</option>{["active", "maintenance", "stored", "project", "out_of_service", "sold", "archived", "retired"].map((item) => <option key={item} value={item}>{item}</option>)}</select><select aria-label="Vehicle sort" className="rounded-xl border border-white/15 bg-slate-950/70 px-3 py-2 text-sm" value={vehicleSort} onChange={(event) => setVehicleSort(event.target.value)}><option value="attention">Attention</option><option value="primary">Primary first</option><option value="updated">Recently updated</option><option value="mileage">Mileage</option><option value="name">Name</option><option value="year">Year</option></select><select aria-label="Selected vehicle" className="rounded-xl border border-white/15 bg-slate-950/70 px-3 py-2 text-sm" value={vehicle?.id ?? ""} onChange={(event) => garage.selectVehicle(event.target.value)}><option value="">Select a vehicle</option>{visibleVehicles.map((item) => <option key={item.id} value={item.id}>{item.nickname} · {item.year} {item.make} {item.model}</option>)}</select></div></header><GarageCollectionsPanel /><GarageM4Experience data={garage.data} selectedVehicle={vehicle} collectionId={collectionFilter !== "all" ? collectionFilter : undefined} onSelectVehicle={(id) => garage.selectVehicle(id)} onQuickAction={(action) => { setTab(action === "Fuel" ? "Overview" : action); setEditing(null); }} onSaveCollection={garage.saveCollection} onLifecycleStatus={updateVehicleLifecycle} />
    <nav aria-label="Garage sections" className="flex flex-wrap gap-2 border-b border-white/10 pb-3">{tabs.map((item) => <button key={item} onClick={() => { setTab(item); setEditing(null); }} className={`rounded-full px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-cyan-200 ${tab === item ? "bg-cyan-300/20 text-cyan-100" : "text-white/60 hover:bg-white/10"}`}>{item}</button>)}</nav>
    {shouldShowVehicleLimitGate ? <Panel title="Add vehicle"><GarageCosmicPlusGate title="You've reached the Free Garage limit" detail={`Cosmic Free supports up to ${vehicleLimit.limit ?? 3} active vehicles. Your existing vehicle data is safe; Cosmic+ includes unlimited active vehicles.`} onBack={closeAddVehicle} /></Panel> : (isAddingVehicle || !vehicle) ? <Panel title="Add vehicle" action={<button type="button" className="rounded-xl border border-white/15 px-3 py-2 text-sm text-white/70 focus:outline-none focus:ring-2 focus:ring-cyan-200" onClick={closeAddVehicle}>Back to Garage</button>}><label className="block max-w-xl text-sm text-white/70">How do you want to add your vehicle?<select aria-label="How do you want to add your vehicle?" className={input} value={onboardingMethod} onChange={(event) => { const next = event.target.value as AddVehicleMethod; setOnboardingMethod(next); setScanKind(null); if (next !== "vin") setDecodedVin(null); if (next !== "plate") setDecodedPlate(null); }}><option value="scan">Scan with Camera · COSMIC+</option><option value="plate">License plate lookup · COSMIC+</option><option value="vin">VIN lookup · COSMIC+</option><option value="manual">Enter manually</option><option value="connected">Connect vehicle</option><option value="obd2">Connect OBD-II</option></select></label>{onboardingMethod === "scan" && !scanKind && <CameraChoice allowed={entitlements.features["garage.advanced"]} onSelect={setScanKind} onManual={() => setOnboardingMethod("manual")} />}{onboardingMethod === "scan" && scanKind && entitlements.features["garage.advanced"] && <VehicleScanner kind={scanKind} onCancel={() => setScanKind(null)} onConfirm={(result) => { if (result.kind === "vin") { setOnboardingVin(result.value); setOnboardingMethod("vin"); } else { setOnboardingPlate(result.value); setOnboardingRegion(result.region ?? ""); setOnboardingMethod("plate"); } setScanKind(null); }} />}{onboardingMethod === "manual" && <VehicleForm vehicle={{ collectionId: collectionFilter !== "all" ? collectionFilter : undefined }} onSubmit={submitVehicle} collections={garage.data.collections} vin={onboardingVin} onVinChange={setOnboardingVin} />}{onboardingMethod === "vin" && !decodedVin && <VinLookup allowed={entitlements.features["garage.advanced"]} value={onboardingVin} onChange={(value) => { setOnboardingVin(value); setDecodedVin(null); }} onSuccess={(value) => { setOnboardingVin(value.vin); setDecodedVin(value); }} onManual={() => setOnboardingMethod("manual")} />}{onboardingMethod === "vin" && decodedVin && <><VinSuccessSummary specifications={decodedVin} /><VehicleForm vehicle={decodedVehicleDraft(decodedVin)} onSubmit={submitVehicle} collections={garage.data.collections} vin={decodedVin.vin} onVinChange={(value) => { setOnboardingVin(value); if (normalizeVin(value) !== decodedVin.vin) setDecodedVin(null); }} /></>}{onboardingMethod === "plate" && <PlateLookup key={`${onboardingPlate}:${onboardingRegion}`} allowed={entitlements.features["garage.advanced"]} initialPlate={onboardingPlate} initialRegion={onboardingRegion} onManual={() => setOnboardingMethod("manual")} onSuccess={(value) => { setDecodedPlate(value); if (value.vin) { const decoded: DecodedVin = { vin: value.vin, source: "nhtsa-vpic", decodedAt: new Date().toISOString(), ...value.specifications }; setDecodedVin(decoded); } }} />}{onboardingMethod === "plate" && decodedPlate && <><PlateSuccessSummary result={decodedPlate} /><VehicleForm vehicle={decodedPlateVehicleDraft(decodedPlate)} onSubmit={submitVehicle} collections={garage.data.collections} vin={decodedPlate.vin} onVinChange={() => undefined} /></>}{onboardingMethod === "connected" && <UnavailableMethod title="Connect vehicle" detail="Connected vehicle providers are not available in this web experience yet." />}{onboardingMethod === "obd2" && <UnavailableMethod title="Connect OBD-II" detail="OBD-II hardware and web connection are not implemented yet; mobile support is planned." />}</Panel> : <>
      <section className="rounded-3xl border border-white/15 bg-white/[0.07] p-5 backdrop-blur-xl"><div className="flex flex-wrap justify-between gap-3"><div><p className="text-xs uppercase tracking-[.18em] text-cyan-100/60">{vehicle.status}</p><h2 className="mt-1 text-2xl font-semibold">{vehicle.nickname}</h2><p className="text-white/60">{vehicle.year} {vehicle.make} {vehicle.model}{vehicle.trim ? ` ${vehicle.trim}` : ""} · {vehicle.currentMileage.toLocaleString()} mi</p></div><div className="flex gap-2"><button className={button} onClick={() => setEditing(editing === "vehicle" ? null : "vehicle")}>Edit vehicle</button><button className="rounded-xl border border-red-300/25 px-3 py-2 text-sm text-red-100" onClick={() => window.confirm(`Delete ${vehicle.nickname}? Its local Garage maintenance, service, issue, modification, expense, reminder, and mileage records will also be removed.`) && garage.removeVehicle(vehicle.id)}>Delete</button></div></div>{editing === "vehicle" && <VehicleForm vehicle={vehicle} onSubmit={(event) => submitVehicle(event, vehicle)} collections={garage.data.collections} />}</section>
      <section aria-labelledby="my-cars-heading"><div className="mb-3 flex flex-wrap items-center justify-between gap-3"><h2 id="my-cars-heading" className="text-xl font-medium">My Cars</h2><button type="button" className={button} onClick={openAddVehicle}>+ Add Vehicle</button></div>{visibleVehicles.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{visibleVehicles.map((item) => <button key={item.id} className={`rounded-2xl border p-3 text-left ${item.id === vehicle.id ? "border-cyan-200/50 bg-cyan-300/10" : "border-white/10 bg-black/10"}`} onClick={() => garage.selectVehicle(item.id)}><p className="font-medium">{item.nickname || `${item.year} ${item.make} ${item.model}`}</p><p className="text-xs text-white/55">{item.year} {item.make} {item.model} · {item.currentMileage.toLocaleString()} mi</p>{item.classification && <span className="mt-2 inline-block text-xs text-white/55 capitalize">{item.classification} vehicle</span>}{item.isPrimary && <span className="mt-2 ml-2 inline-block text-xs text-cyan-100">Primary vehicle</span>}</button>)}<AddVehicleTile onClick={openAddVehicle} /></div> : <div className="rounded-2xl border border-dashed border-white/15 bg-black/10 p-5"><p className="text-sm text-white/60">No vehicles match these filters.</p><button type="button" className={`mt-3 ${button}`} onClick={openAddVehicle}>Add Vehicle</button></div>}</section>
      {tab === "Overview" && <Overview vehicle={vehicle} summary={summary} attention={attention.length} overLimit={vehicleLimit.overLimit} activeVehicleCount={activeVehicleCount} vehicleLimit={vehicleLimit.limit} />}
      {tab === "Mileage" && <Panel title="Mileage history"><p className="text-sm text-white/55">Current derived mileage: <span className="text-white">{summary?.currentMileage.toLocaleString()} mi</span>{summary?.averageMonthlyMileage !== undefined ? ` · average ${Math.round(summary.averageMonthlyMileage).toLocaleString()} mi/month` : " · add at least three months of readings for an average"}</p><form className="grid gap-3 sm:grid-cols-3" onSubmit={saveMileage}><Text name="mileage" label="Odometer mileage" type="number" required/><Text name="date" label="Date" type="date" value={localDateValue()}/><Text name="note" label="Note"/><button className={button}>Add mileage</button></form><div className="mt-4 space-y-2">{summary?.mileageHistory.length ? summary.mileageHistory.map((entry) => <Record key={entry.id} title={`${entry.mileage.toLocaleString()} miles`} detail={`${entry.date}${entry.note ? ` · ${entry.note}` : ""}`} actions={<span className="text-white/45">{entry.source ?? "user"}</span>} />) : <Empty label="Add a few dated readings to build mileage history." />}</div></Panel>}
      {tab === "Maintenance" && <Panel title="Maintenance" action={<button className={button} onClick={() => setEditing(editing === "maintenance:new" ? null : "maintenance:new")}>+ Add maintenance</button>}>{editing === "maintenance:new" && <MaintenanceForm onSubmit={saveMaintenance} vehicle={vehicle} />}{summary?.maintenance.map((item) => editing === `maintenance:${item.id}` ? <MaintenanceForm key={item.id} item={item} vehicle={vehicle} onSubmit={(event) => saveMaintenance(event, item)} /> : <Record key={item.id} title={item.name} detail={`${summary.statusById.get(item.id)?.replace(/([A-Z])/g, " $1")} · ${item.priority} priority`} actions={<><button onClick={() => setEditing(`maintenance:${item.id}`)}>Edit</button><button onClick={() => markServiced(item)} className="text-cyan-100">Mark serviced</button><button onClick={() => remove("maintenance item", () => garage.removeMaintenance(item.id))}>Delete</button></>} />) ?? <Empty label="No maintenance items." />}</Panel>}
      {tab === "Service" && <Panel title="Service history" action={<button className={button} onClick={() => setEditing(editing === "service:new" ? null : "service:new")}>+ Add service</button>}>{editing === "service:new" && <ServiceForm vehicle={vehicle} maintenance={summary?.maintenance ?? []} onSubmit={saveService} />}{summary?.services.map((item) => editing === `service:${item.id}` ? <ServiceForm key={item.id} item={item} vehicle={vehicle} maintenance={summary?.maintenance ?? []} onSubmit={(event) => saveService(event, item)} /> : <Record key={item.id} title={item.title} detail={`${item.date}${item.cost !== undefined ? ` · ${money.format(item.cost)}` : ""}`} actions={<><button onClick={() => setEditing(`service:${item.id}`)}>Edit</button><button onClick={() => remove("service record", () => garage.removeService(item.id))}>Delete</button></>} />) ?? <Empty label="No service history." />}</Panel>}
      {tab === "Issues" && <Panel title="Issues" action={<button className={button} onClick={() => setEditing(editing === "issue:new" ? null : "issue:new")}>+ Add issue</button>}>{editing === "issue:new" && <IssueForm onSubmit={saveIssue} vehicle={vehicle} />}{summary?.issues.map((item) => editing === `issue:${item.id}` ? <IssueForm key={item.id} item={item} vehicle={vehicle} onSubmit={(event) => saveIssue(event, item)} /> : <Record key={item.id} title={item.title} detail={`${item.severity} · ${item.status}`} urgent={item.status !== "resolved" && ["high", "critical"].includes(item.severity)} actions={<><button onClick={() => setEditing(`issue:${item.id}`)}>Edit</button><button onClick={() => garage.saveIssue({ ...item, status: item.status === "resolved" ? "open" : "resolved", resolvedAt: item.status === "resolved" ? undefined : localDateValue() })}>{item.status === "resolved" ? "Reopen" : "Resolve"}</button><button onClick={() => remove("issue", () => garage.removeIssue(item.id))}>Delete</button></>} />) ?? <Empty label="No issues." />} {summary?.issues.map((item) => <RepairOptions key={`repair:${item.id}`} vehicle={vehicle} issue={item} allowed={entitlements.features["garage.advanced"]} estimates={garage.data.repairEstimates.filter((estimate) => estimate.issueId === item.id)} onSaveEstimate={garage.saveRepairEstimate} />)}</Panel>}
      {tab === "Modifications" && <Panel title="Modifications" action={<button className={button} onClick={() => setEditing(editing === "mod:new" ? null : "mod:new")}>+ Add modification</button>}>{editing === "mod:new" && <ModificationForm vehicle={vehicle} onSubmit={saveModification} />}{summary?.modifications.map((item) => editing === `mod:${item.id}` ? <ModificationForm key={item.id} item={item} vehicle={vehicle} onSubmit={(event) => saveModification(event, item)} /> : <Record key={item.id} title={item.name} detail={item.category} actions={<><button onClick={() => setEditing(`mod:${item.id}`)}>Edit</button><button onClick={() => remove("modification", () => garage.removeModification(item.id))}>Delete</button></>} />) ?? <Empty label="No modifications." />}</Panel>}
      {tab === "Expenses" && <Expenses vehicle={vehicle} expenses={summary?.expenses ?? []} editing={editing} setEditing={setEditing} save={saveExpense} remove={(item) => remove("expense", () => garage.removeExpense(item.id))} />}
      {tab === "Reminders" && <Panel title="Reminders" action={<button className={button} onClick={() => setEditing(editing === "reminder:new" ? null : "reminder:new")}>+ Add reminder</button>}>{editing === "reminder:new" && <ReminderForm vehicle={vehicle} onSubmit={saveReminder} />}{summary?.reminders.map((item) => editing === `reminder:${item.id}` ? <ReminderForm key={item.id} item={item} vehicle={vehicle} onSubmit={(event) => saveReminder(event, item)} /> : <Record key={item.id} title={item.title} detail={reminderStatus(item, vehicle.currentMileage).replace(/([A-Z])/g, " $1")} actions={<><button onClick={() => setEditing(`reminder:${item.id}`)}>Edit</button><button onClick={() => garage.saveReminder({ ...item, completed: !item.completed })}>{item.completed ? "Uncomplete" : "Complete"}</button><button onClick={() => remove("reminder", () => garage.removeReminder(item.id))}>Delete</button></>} />) ?? <Empty label="No reminders." />}</Panel>}
    </>}</div>;
}

function UnavailableMethod({ title, detail, premium, onManual }: { title: string; detail: string; premium?: boolean; onManual?: () => void }) { return premium ? <GarageCosmicPlusGate title={title} detail="License Plate Lookup is available with Cosmic+. Enter the vehicle manually on Free." alternative={<button type="button" onClick={onManual} className="rounded-xl border border-white/15 px-4 py-2.5 text-sm text-white/70 transition hover:bg-white/[0.08] focus:outline-none focus:ring-2 focus:ring-cyan-200">Enter manually</button>} /> : <div className="mt-4 rounded-xl border border-amber-200/15 bg-amber-300/5 p-4"><h3 className="font-medium">{title}</h3><p className="mt-1 text-sm text-white/60">{detail}</p><p className="mt-3 text-xs text-white/45">Choose another method above to continue.</p></div>; }
const usStates = [["AL", "Alabama"], ["AK", "Alaska"], ["AZ", "Arizona"], ["AR", "Arkansas"], ["CA", "California"], ["CO", "Colorado"], ["CT", "Connecticut"], ["DE", "Delaware"], ["DC", "District of Columbia"], ["FL", "Florida"], ["GA", "Georgia"], ["HI", "Hawaii"], ["ID", "Idaho"], ["IL", "Illinois"], ["IN", "Indiana"], ["IA", "Iowa"], ["KS", "Kansas"], ["KY", "Kentucky"], ["LA", "Louisiana"], ["ME", "Maine"], ["MD", "Maryland"], ["MA", "Massachusetts"], ["MI", "Michigan"], ["MN", "Minnesota"], ["MS", "Mississippi"], ["MO", "Missouri"], ["MT", "Montana"], ["NE", "Nebraska"], ["NV", "Nevada"], ["NH", "New Hampshire"], ["NJ", "New Jersey"], ["NM", "New Mexico"], ["NY", "New York"], ["NC", "North Carolina"], ["ND", "North Dakota"], ["OH", "Ohio"], ["OK", "Oklahoma"], ["OR", "Oregon"], ["PA", "Pennsylvania"], ["RI", "Rhode Island"], ["SC", "South Carolina"], ["SD", "South Dakota"], ["TN", "Tennessee"], ["TX", "Texas"], ["UT", "Utah"], ["VT", "Vermont"], ["VA", "Virginia"], ["WA", "Washington"], ["WV", "West Virginia"], ["WI", "Wisconsin"], ["WY", "Wyoming"]] as const;
function CameraChoice({ allowed, onSelect, onManual }: { allowed: boolean; onSelect: (kind: VehicleScanKind) => void; onManual: () => void }) { if (!allowed) return <GarageCosmicPlusGate title="Camera Vehicle Lookup is included with Cosmic+" detail="Scan a VIN or license plate to identify and autofill your vehicle. Enter the vehicle manually on Free." alternative={<button type="button" onClick={onManual} className="rounded-xl border border-white/15 px-4 py-2.5 text-sm text-white/70">Enter manually</button>} />; return <section className="mt-4 max-w-xl rounded-2xl border border-cyan-200/15 bg-cyan-300/[0.05] p-4" aria-labelledby="camera-choice-title"><h3 id="camera-choice-title" className="font-medium">Camera Vehicle Lookup</h3><p className="mt-1 text-sm text-white/55">Choose what you want to scan. Camera permission is requested only after you choose and press Start Camera.</p><div className="mt-4 flex flex-wrap gap-2"><button type="button" className={button} onClick={() => onSelect("plate")}>Scan License Plate</button><button type="button" className={button} onClick={() => onSelect("vin")}>Scan VIN</button></div></section>; }
function PlateLookup({ allowed, initialPlate = "", initialRegion = "UT", onSuccess, onManual }: { allowed: boolean; initialPlate?: string; initialRegion?: string; onSuccess: (value: DecodedPlate) => void; onManual: () => void }) { const [region, setRegion] = useState(initialRegion); const [plate, setPlate] = useState(initialPlate); const [message, setMessage] = useState(""); const [loading, setLoading] = useState(false); if (!allowed) return <GarageCosmicPlusGate title="License Plate Lookup is available with Cosmic+" detail="Find your vehicle using the plate you already know. Enter the vehicle manually on Free." alternative={<button type="button" onClick={onManual} className="rounded-xl border border-white/15 px-4 py-2.5 text-sm text-white/70 transition hover:bg-white/[0.08] focus:outline-none focus:ring-2 focus:ring-cyan-200">Enter manually</button>} />; const lookup = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const normalized = plate.trim().toUpperCase(); if (!normalized) { setMessage("Enter a license plate."); return; } setLoading(true); setMessage("Finding vehicle…"); try { const response = await fetch("/api/garage/plate-lookup", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ plate: normalized, region, country: "US" }) }); const payload = await response.json() as { plate?: string; region?: string; vin?: string; specifications?: Partial<VehicleVinSpecifications>; sources?: string[]; error?: string }; if (!response.ok || !payload.plate) { setMessage(payload.error ?? "We couldn't identify that plate. Try VIN lookup or enter the vehicle manually."); return; } onSuccess({ plate: payload.plate, region: payload.region ?? region, vin: payload.vin, specifications: payload.specifications ?? {}, sources: payload.sources ?? ["CarsXE"] }); } catch { setMessage("Plate lookup is temporarily unavailable. Try VIN lookup or enter the vehicle manually."); } finally { setLoading(false); } }; return <div className="mt-4 max-w-xl rounded-xl border border-cyan-200/15 bg-cyan-300/5 p-4"><form className="space-y-3" onSubmit={lookup}><label className="block text-sm text-white/70">State / Region<select className={input} value={region} onChange={(event) => setRegion(event.target.value)}>{usStates.map(([code, name]) => <option key={code} value={code}>{name} ({code})</option>)}</select></label><label className="block text-sm text-white/70">License plate<input className={input} value={plate} onChange={(event) => setPlate(event.target.value)} autoCapitalize="characters" autoComplete="off" required /></label><button className={button} type="submit" disabled={loading}>{loading ? "Finding vehicle…" : "Find Vehicle"}</button></form><p className="mt-2 text-xs text-white/60" aria-live="polite">{message}</p><button type="button" className="mt-3 block text-sm text-cyan-100 underline underline-offset-4" onClick={onManual}>Enter manually instead</button></div>; }
function Panel({ title, action, children }: { title: string; action?: ReactNode; children: ReactNode }) { return <section className="rounded-3xl border border-white/15 bg-white/[0.07] p-5 backdrop-blur-xl"><div className="flex flex-wrap items-center justify-between gap-3"><h2 className="text-xl font-medium">{title}</h2>{action}</div><div className="mt-4 space-y-3">{children}</div></section>; }
function Record({ title, detail, urgent, actions }: { title: string; detail: string; urgent?: boolean; actions: ReactNode }) { return <div className={`flex flex-wrap items-center justify-between gap-3 rounded-xl border p-3 ${urgent ? "border-red-300/35 bg-red-300/10" : "border-white/10 bg-black/10"}`}><div><p className="font-medium">{title}</p><p className="text-sm text-white/55">{detail}</p></div><div className="flex flex-wrap gap-3 text-xs text-white/65">{actions}</div></div>; }
function Empty({ label }: { label: string }) { return <p className="py-4 text-sm text-white/55">{label}</p>; }
function AddVehicleTile({ onClick }: { onClick: () => void }) { return <button type="button" onClick={onClick} className="min-h-28 rounded-2xl border border-dashed border-cyan-200/25 bg-cyan-300/[.04] p-4 text-left text-cyan-50/90 transition hover:border-cyan-200/45 hover:bg-cyan-300/[.08] focus:outline-none focus:ring-2 focus:ring-cyan-200"><p className="font-medium">+ Add Vehicle</p><p className="mt-1 text-sm text-white/50">Add another car to Garage</p></button>; }
function VehicleForm({ vehicle, collections = [], vin = "", onVinChange, vinLookup = false, onSubmit }: { vehicle?: Partial<Vehicle>; collections?: GarageCollection[]; vin?: string; onVinChange?: (value: string) => void; vinLookup?: boolean; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { const collectionOptions = collections.length ? collections : [{ id: "my-garage", name: "My Garage" }]; return <form className="mt-4 grid gap-3 sm:grid-cols-2" onSubmit={onSubmit}><Text name="nickname" label="Nickname" value={vehicle?.nickname} required/><Text name="year" label="Year" value={vehicle?.year} type="number" required/><Text name="make" label="Make" value={vehicle?.make} required/><Text name="model" label="Model" value={vehicle?.model} required/><Text name="trim" label="Trim" value={vehicle?.trim}/><Select name="vehicleType" label="Type" value={vehicle?.vehicleType ?? "car"} values={["car", "truck", "SUV", "motorcycle", "ATV/UTV", "other"]}/><Select name="classification" label="Use" value={vehicle?.classification ?? "daily"} values={["daily", "project", "track", "work", "other"]}/><Select name="collectionId" label="Collection" value={vehicle?.collectionId ?? "my-garage"} values={collectionOptions.map((item) => item.id)} labels={Object.fromEntries(collectionOptions.map((item) => [item.id, item.name]))}/><Text name="mileage" label="Current mileage" value={vehicle?.currentMileage} type="number" required/><Text name="plate" label="License plate" value={vehicle?.licensePlate}/><Text name="vin" label="VIN" value={vehicle?.vin ?? vin} onChange={(event) => onVinChange?.(event.currentTarget.value)}/>{vinLookup && <VinDecoder onVinChange={onVinChange}/>}<Text name="color" label="Color" value={vehicle?.color}/><Text name="purchaseDate" label="Purchase date" value={vehicle?.purchaseDate} type="date"/><Text name="purchasePrice" label="Purchase price" value={vehicle?.purchasePrice} type="number"/><Select name="status" label="Status" value={vehicle?.status === "project" ? "active" : vehicle?.status ?? "active"} values={["active", "maintenance", "stored", "out_of_service", "sold", "archived", "retired"]}/><label className="flex items-center gap-2 text-sm text-white/70"><input name="primary" type="checkbox" defaultChecked={vehicle?.isPrimary}/><span>Primary vehicle</span></label><Text name="notes" label="Notes" value={vehicle?.notes}/><button className={button}>{vehicle ? "Save changes" : "Add vehicle"}</button><button type="button" className="text-sm text-white/55" onClick={(event) => event.currentTarget.form?.reset()}>Cancel</button></form>; }
function VinDecoder({ onVinChange }: { onVinChange?: (value: string) => void }) { const [result, setResult] = useState<Record<string, string> | null>(null); const [message, setMessage] = useState(""); const [loading, setLoading] = useState(false); const fillEmpty = (form: HTMLFormElement, name: string, value?: string) => { if (!value) return; const control = form.elements.namedItem(name); if (!(control instanceof HTMLInputElement || control instanceof HTMLSelectElement) || control.value.trim()) return; if (control instanceof HTMLSelectElement && !Array.from(control.options).some((option) => option.value === value)) return; control.value = value; control.dispatchEvent(new Event("input", { bubbles: true })); control.dispatchEvent(new Event("change", { bubbles: true })); }; const decode = async (event: React.MouseEvent<HTMLButtonElement>) => { const form = event.currentTarget.form; if (!form) return; const vin = field(new FormData(form).get("vin")).replace(/\s+/g, "").toUpperCase(); const vinControl = form.elements.namedItem("vin"); if (vinControl instanceof HTMLInputElement) vinControl.value = vin; onVinChange?.(vin); if (!/^[A-HJ-NPR-Z0-9]{17}$/.test(vin)) return setMessage("Enter a valid 17-character VIN."); setLoading(true); setMessage("Decoding…"); setResult(null); try { const response = await fetch(`/api/garage/vin/${encodeURIComponent(vin)}`, { cache: "no-store" }); const payload = await response.json() as { specifications?: Record<string, string>; error?: string }; if (!response.ok || !payload.specifications) return setMessage(payload.error ?? "VIN decoding temporarily unavailable."); const specifications = payload.specifications; fillEmpty(form, "year", specifications.modelYear); fillEmpty(form, "make", specifications.make); fillEmpty(form, "model", specifications.model); fillEmpty(form, "trim", specifications.trim); fillEmpty(form, "vehicleType", specifications.vehicleType); setResult(specifications); setMessage("Vehicle found · Auto-filled from NHTSA vPIC. Review and edit before saving."); } catch { setMessage("VIN decoding temporarily unavailable. You can switch to manual entry and keep this VIN."); } finally { setLoading(false); } }; return <div className="sm:col-span-2 rounded-xl border border-cyan-200/15 bg-cyan-300/5 p-3"><button type="button" className={button} onClick={decode} disabled={loading}>{loading ? "Decoding…" : "Decode VIN"}</button><p className="mt-2 text-xs text-white/60" aria-live="polite">{message}</p>{result && <p className="mt-2 text-xs text-cyan-100/70">Source: NHTSA vPIC · {Object.entries(result).map(([key, value]) => `${key}: ${value}`).join(" · ")}</p>}</div>; }
function normalizeVin(value: string) { return value.replace(/\s+/g, "").toUpperCase(); }
function decodedVehicleDraft(specifications: DecodedVin): Partial<Vehicle> { return { vin: specifications.vin, year: specifications.modelYear ? Number(specifications.modelYear) : undefined, make: specifications.make, model: specifications.model, trim: specifications.trim, vehicleType: specifications.vehicleType, vinSpecifications: specifications }; }
function decodedPlateVehicleDraft(result: DecodedPlate): Partial<Vehicle> { return { licensePlate: result.plate, vin: result.vin, year: result.specifications.modelYear ? Number(result.specifications.modelYear) : undefined, make: result.specifications.make, model: result.specifications.model, trim: result.specifications.trim, vehicleType: result.specifications.vehicleType }; }
function VinSuccessSummary({ specifications }: { specifications: DecodedVin }) { const identity = [specifications.modelYear, specifications.make, specifications.model, specifications.trim].filter(Boolean).join(" "); return <div className="mt-4 rounded-xl border border-cyan-200/15 bg-cyan-300/5 p-3" role="status"><p className="font-medium">✓ {identity || "Vehicle identified"}</p><p className="mt-1 text-xs text-white/55">Vehicle information from NHTSA vPIC</p></div>; }
function PlateSuccessSummary({ result }: { result: DecodedPlate }) { const identity = [result.specifications.modelYear, result.specifications.make, result.specifications.model, result.specifications.trim].filter(Boolean).join(" "); return <div className="mt-4 rounded-xl border border-cyan-200/15 bg-cyan-300/5 p-3" role="status"><p className="font-medium">✓ {identity || "Vehicle identified from plate"}</p><p className="mt-1 text-xs text-white/55">{result.plate} · {result.region} · {result.sources.join(" + ")}. Review before saving.</p></div>; }
function VinLookup({ allowed, value, onChange, onSuccess, onManual }: { allowed: boolean; value: string; onChange: (value: string) => void; onSuccess: (value: DecodedVin) => void; onManual: () => void }) { const [message, setMessage] = useState(""); const [requiresPlus, setRequiresPlus] = useState(false); const [loading, setLoading] = useState(false); if (!allowed) return <GarageCosmicPlusGate title="VIN Lookup is available with Cosmic+" detail="Automatically identify and fill vehicle information from the VIN. Enter the vehicle manually on Free." alternative={<button type="button" onClick={onManual} className="rounded-xl border border-white/15 px-4 py-2.5 text-sm text-white/70 transition hover:bg-white/[0.08] focus:outline-none focus:ring-2 focus:ring-cyan-200">Enter manually</button>} />; const lookup = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const vin = normalizeVin(value); onChange(vin); setRequiresPlus(false); if (!/^[A-HJ-NPR-Z0-9]{17}$/.test(vin)) { setMessage("Enter a valid 17-character VIN."); return; } setLoading(true); setMessage("Looking up…"); try { const response = await fetch(`/api/garage/vin/${encodeURIComponent(vin)}`, { cache: "no-store" }); const payload = await response.json() as { source?: "nhtsa-vpic"; decodedAt?: string; specifications?: Record<string, string>; error?: string }; if (!response.ok || !payload.specifications) { setRequiresPlus(response.status === 401 || response.status === 403); setMessage(payload.error ?? "We couldn't identify this VIN. Check the VIN and try again, or enter the vehicle manually."); return; } onSuccess({ vin, source: payload.source ?? "nhtsa-vpic", decodedAt: payload.decodedAt ?? new Date().toISOString(), ...payload.specifications } as DecodedVin); } catch { setMessage("We couldn't identify this VIN. Check the VIN and try again, or enter the vehicle manually."); } finally { setLoading(false); } }; return <div className="mt-4 max-w-xl rounded-xl border border-cyan-200/15 bg-cyan-300/5 p-4"><form className="space-y-3" onSubmit={lookup}><Text name="lookupVin" label="VIN" value={value} onChange={(event) => onChange(event.currentTarget.value)} required/><button className={button} type="submit" disabled={loading}>{loading ? "Looking up…" : "Look Up Vehicle"}</button></form><p className="mt-2 text-xs text-white/60" aria-live="polite">{message}</p>{requiresPlus ? <Link href="/cosmic-plus" className="mt-3 inline-flex rounded-xl border border-fuchsia-200/20 bg-fuchsia-200/10 px-3 py-2 text-sm text-fuchsia-50">Upgrade to Cosmic+</Link> : null}<button type="button" className="mt-3 block text-sm text-cyan-100 underline underline-offset-4" onClick={onManual}>Enter manually</button></div>; }
function MaintenanceForm({ item, vehicle, onSubmit }: { item?: VehicleMaintenanceItem; vehicle: Vehicle; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form className="grid gap-3 rounded-xl border border-cyan-200/20 bg-cyan-300/5 p-3 sm:grid-cols-2" onSubmit={onSubmit}><Text name="name" label="Name" value={item?.name} required/><Select name="priority" label="Priority" value={item?.priority ?? "medium"} values={["low", "medium", "high"]}/><Text name="intervalMiles" label="Interval miles" value={item?.intervalMiles} type="number"/><Text name="intervalMonths" label="Interval months" value={item?.intervalMonths} type="number"/><Text name="lastMileage" label="Last service mileage" value={item?.lastServiceMileage ?? vehicle.currentMileage} type="number"/><Text name="lastDate" label="Last service date" value={item?.lastServiceDate} type="date"/><Text name="nextMileage" label="Next due mileage" value={item?.nextDueMileage} type="number"/><Text name="nextDate" label="Next due date" value={item?.nextDueDate} type="date"/><Text name="notes" label="Notes" value={item?.notes}/><button className={button}>{item ? "Save changes" : "Create maintenance"}</button></form>; }
function ServiceForm({ item, vehicle, maintenance, onSubmit }: { item?: VehicleServiceRecord; vehicle: Vehicle; maintenance: VehicleMaintenanceItem[]; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form className="grid gap-3 rounded-xl border border-cyan-200/20 bg-cyan-300/5 p-3 sm:grid-cols-2" onSubmit={onSubmit}><Text name="title" label="Title" value={item?.title} required/><Text name="date" label="Date" value={item?.date ?? localDateValue()} type="date" required/><Text name="mileage" label="Mileage" value={item?.mileage ?? vehicle.currentMileage} type="number"/><Text name="cost" label="Cost" value={item?.cost} type="number"/><Text name="shop" label="Shop/location" value={item?.shop}/><Select name="maintenance" label="Linked maintenance" value={item?.maintenanceItemId ?? ""} values={["", ...maintenance.map((entry) => entry.id)]} labels={Object.fromEntries(maintenance.map((entry) => [entry.id, entry.name]))}/><Text name="description" label="Description" value={item?.description}/><button className={button}>{item ? "Save changes" : "Add service"}</button></form>; }
function IssueForm({ item, vehicle, onSubmit }: { item?: VehicleIssue; vehicle: Vehicle; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form className="grid gap-3 rounded-xl border border-cyan-200/20 bg-cyan-300/5 p-3 sm:grid-cols-2" onSubmit={onSubmit}><Text name="title" label="Title" value={item?.title} required/><Select name="severity" label="Severity" value={item?.severity ?? "medium"} values={["low", "medium", "high", "critical"]}/><Select name="status" label="Status" value={item?.status ?? "open"} values={["open", "monitoring", "resolved"]}/><Text name="reportedAt" label="Reported date" value={item?.reportedAt ?? localDateValue()} type="date"/><Text name="mileage" label="Mileage" value={item?.mileage ?? vehicle.currentMileage} type="number"/><Text name="description" label="Description" value={item?.description}/><Text name="notes" label="Notes" value={item?.notes}/><button className={button}>{item ? "Save changes" : "Add issue"}</button></form>; }
function RepairOptions({ vehicle, issue, allowed, estimates, onSaveEstimate }: { vehicle: Vehicle; issue: VehicleIssue; allowed: boolean; estimates: GarageRepairEstimate[]; onSaveEstimate: (estimate: GarageRepairEstimate) => void }) { const [location, setLocation] = useState(""); const [message, setMessage] = useState(""); const [shops, setShops] = useState<Array<{ name: string; address?: string; rating?: number; reviewCount?: number; website?: string; pricingAvailability: string }>>([]); const [quoteOpen, setQuoteOpen] = useState(false); const [loading, setLoading] = useState(false); const findOptions = async () => { if (!allowed) return; if (!location.trim()) { setMessage("Enter a ZIP code or city to search nearby shops."); return; } setLoading(true); setMessage("Checking available repair options…"); try { const estimateResponse = await fetch("/api/garage/repair-estimate", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ vehicleId: vehicle.id, issueId: issue.id, category: issue.title, region: location.trim() }) }); const estimatePayload = await estimateResponse.json() as { error?: string; estimate?: GarageRepairEstimate }; if (estimatePayload.estimate) onSaveEstimate({ ...estimatePayload.estimate, vehicleId: vehicle.id, issueId: issue.id }); const shopResponse = await fetch("/api/garage/repair-shops", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ query: location.trim(), service: issue.title }) }); const shopPayload = await shopResponse.json() as { error?: string; shops?: typeof shops }; setShops(shopPayload.shops ?? []); setMessage([estimatePayload.error, shopPayload.error].filter(Boolean).join(" ") || "Repair options loaded."); } catch { setMessage("Repair options are temporarily unavailable. You can record a quote manually."); } finally { setLoading(false); } }; const saveQuote = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const min = optionalNumber(data.get("min")); const max = optionalNumber(data.get("max")); const amount = optionalNumber(data.get("amount")); if (min === undefined && max === undefined && amount === undefined) { setMessage("Enter a quote amount or range."); return; } const totalMinMinor = Math.round(((amount ?? min ?? max ?? 0) * 100)); const totalMaxMinor = Math.round(((amount ?? max ?? min ?? 0) * 100)); onSaveEstimate({ id: makeId(), vehicleId: vehicle.id, issueId: issue.id, category: issue.title, description: field(data.get("description")) || undefined, source: field(data.get("shop")) || "User-entered quote", sourceType: "user-quote", shop: field(data.get("shop")) || undefined, totalMinMinor: Math.min(totalMinMinor, totalMaxMinor), totalMaxMinor: Math.max(totalMinMinor, totalMaxMinor), currency: "USD", region: location.trim() || undefined, status: "quoted", timestamp: new Date().toISOString(), availability: "available", notes: field(data.get("notes")) || undefined }); setQuoteOpen(false); event.currentTarget.reset(); setMessage("Quote saved to Garage history. It is not recorded spending until a completed expense or service is logged."); }; return <div className="mt-3 rounded-2xl border border-amber-200/15 bg-amber-300/[0.04] p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><h3 className="font-medium">Repair Options</h3><p className="text-xs text-white/55">A diagnostic code or issue does not confirm a repair.</p></div>{allowed ? <button type="button" className={button} onClick={() => setQuoteOpen((value) => !value)}>Record shop quote</button> : null}</div>{allowed ? <><div className="mt-3 flex flex-wrap gap-2"><input className={`${input} mt-0 max-w-xs`} aria-label="Repair search ZIP or city" placeholder="ZIP code or city" value={location} onChange={(event) => setLocation(event.target.value)} /><button type="button" className={button} onClick={findOptions} disabled={loading}>{loading ? "Searching…" : "Find Repair Options"}</button></div><p className="mt-2 text-xs text-white/55" aria-live="polite">{message}</p>{estimates.length ? <div className="mt-3 space-y-1 text-sm">{estimates.slice(-3).reverse().map((estimate) => <p key={estimate.id}>{estimate.sourceType.replace("-", " ")} · {estimate.shop ?? estimate.source} · {estimate.totalMinMinor !== undefined ? `$${(estimate.totalMinMinor / 100).toFixed(2)}` : ""}{estimate.totalMaxMinor !== undefined && estimate.totalMaxMinor !== estimate.totalMinMinor ? `–$${(estimate.totalMaxMinor / 100).toFixed(2)}` : ""} · {estimate.status ?? "estimate"}</p>)}</div> : null}{shops.length ? <div className="mt-3 space-y-2">{shops.map((shop) => <div key={`${shop.name}:${shop.address}`} className="rounded-xl border border-white/10 bg-black/10 p-3"><p className="font-medium">{shop.name}</p><p className="text-xs text-white/55">{shop.address ?? "Address unavailable"}{shop.rating !== undefined ? ` · ${shop.rating.toFixed(1)} ★${shop.reviewCount ? ` (${shop.reviewCount})` : ""}` : ""}</p><p className="mt-1 text-xs text-white/45">Price: not published by shop directory</p>{shop.website ? <a className="text-xs text-cyan-100 underline" href={shop.website} target="_blank" rel="noreferrer">Open listing</a> : null}</div>)}</div> : null}{quoteOpen && <form className="mt-3 grid gap-2 sm:grid-cols-2" onSubmit={saveQuote}><Text name="shop" label="Shop"/><Text name="amount" label="Quote amount" type="number"/><Text name="min" label="Range minimum" type="number"/><Text name="max" label="Range maximum" type="number"/><Text name="description" label="Repair/service" value={issue.title}/><Text name="notes" label="Notes"/><button className={button}>Save quote</button></form>}</> : <GarageCosmicPlusGate title="Repair intelligence is included with Cosmic+" detail="Free Garage remains useful: record the issue, service, expense, or a shop quote manually." alternative={<button type="button" onClick={() => setQuoteOpen(true)} className="rounded-xl border border-white/15 px-4 py-2.5 text-sm text-white/70">Continue manually</button>} />}{!allowed && quoteOpen ? <form className="mt-3 grid gap-2 sm:grid-cols-2" onSubmit={saveQuote}><Text name="shop" label="Shop"/><Text name="amount" label="Quote amount" type="number"/><Text name="min" label="Range minimum" type="number"/><Text name="max" label="Range maximum" type="number"/><Text name="description" label="Repair/service" value={issue.title}/><Text name="notes" label="Notes"/><button className={button}>Save quote</button></form> : null}</div>; }
function ModificationForm({ item, vehicle, onSubmit }: { item?: VehicleModification; vehicle: Vehicle; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form className="grid gap-3 rounded-xl border border-cyan-200/20 bg-cyan-300/5 p-3 sm:grid-cols-2" onSubmit={onSubmit}><Text name="name" label="Name" value={item?.name} required/><Select name="category" label="Category" value={item?.category ?? "Other"} values={["Performance", "Suspension", "Wheels/Tires", "Exterior", "Interior", "Audio", "Electrical", "Other"]}/><Select name="status" label="Status" value={item?.status ?? "planned"} values={["planned", "ordered", "purchased", "installed", "removed", "canceled"]}/><Text name="brand" label="Brand" value={item?.brand}/><Text name="partNumber" label="Part number" value={item?.partNumber}/><Text name="purchaseDate" label="Purchase date" value={item?.purchaseDate} type="date"/><Text name="installedAt" label="Installed date" value={item?.installedAt} type="date"/><Text name="mileage" label="Mileage" value={item?.mileage ?? vehicle.currentMileage} type="number"/><Text name="cost" label="Parts cost" value={item?.cost} type="number"/><Text name="laborCost" label="Install/labor cost" value={item?.laborCost} type="number"/><Text name="installer" label="Installer/shop" value={item?.installer}/><Text name="description" label="Notes" value={item?.description}/><button className={button}>{item ? "Save changes" : "Add modification"}</button></form>; }
function ExpenseForm({ item, vehicle, onSubmit }: { item?: VehicleExpense; vehicle: Vehicle; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form className="grid gap-3 rounded-xl border border-cyan-200/20 bg-cyan-300/5 p-3 sm:grid-cols-2" onSubmit={onSubmit}><Text name="date" label="Date" value={item?.date ?? localDateValue()} type="date" required/><Select name="category" label="Category" value={item?.category ?? "Other"} values={["Fuel", "Maintenance", "Repair", "Modification", "Registration", "Insurance", "Other"]}/><Text name="amount" label="Amount" value={item?.amount} type="number" required/><Text name="mileage" label="Mileage" value={item?.mileage ?? vehicle.currentMileage} type="number"/><Text name="description" label="Description" value={item?.description}/><button className={button}>{item ? "Save changes" : "Add expense"}</button></form>; }
function ReminderForm({ item, vehicle, onSubmit }: { item?: VehicleReminder; vehicle: Vehicle; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form className="grid gap-3 rounded-xl border border-cyan-200/20 bg-cyan-300/5 p-3 sm:grid-cols-2" onSubmit={onSubmit}><Text name="title" label="Title" value={item?.title} required/><Text name="dueDate" label="Due date" value={item?.dueDate} type="date"/><Text name="dueMileage" label="Due mileage" value={item?.dueMileage ?? vehicle.currentMileage} type="number"/><button className={button}>{item ? "Save changes" : "Add reminder"}</button></form>; }
function Text({ name, label, value, type = "text", required, onChange }: { name: string; label: string; value?: string | number; type?: string; required?: boolean; onChange?: React.ChangeEventHandler<HTMLInputElement> }) { return <label className="text-sm text-white/70">{label}<input className={input} name={name} type={type} defaultValue={value ?? ""} min={type === "number" ? 0 : undefined} required={required} onChange={onChange}/></label>; }
function Select({ name, label, value, values, labels }: { name: string; label: string; value: string; values: string[]; labels?: Record<string, string> }) { return <label className="text-sm text-white/70">{label}<select className={input} name={name} defaultValue={value}>{values.map((item) => <option key={item} value={item}>{(labels?.[item] ?? item) || "None"}</option>)}</select></label>; }
function Expenses({ vehicle, expenses, editing, setEditing, save, remove }: { vehicle: Vehicle; expenses: VehicleExpense[]; editing: string | null; setEditing: (value: string | null) => void; save: (event: FormEvent<HTMLFormElement>, existing?: VehicleExpense) => void; remove: (item: VehicleExpense) => void }) { const month = localDateValue().slice(0, 7); const year = localDateValue().slice(0, 4); const total = (filter: (item: VehicleExpense) => boolean) => expenses.filter(filter).reduce((sum, item) => sum + item.amount, 0); return <Panel title="Expenses" action={<button className={button} onClick={() => setEditing(editing === "expense:new" ? null : "expense:new")}>+ Add expense</button>}><div className="grid gap-2 sm:grid-cols-3">{[["This month", total((item) => item.date.startsWith(month))], ["This year", total((item) => item.date.startsWith(year))], ["All time", total(() => true)]].map(([label, amount]) => <div key={String(label)} className="rounded-xl bg-black/15 p-3"><p className="text-xs text-white/55">{label}</p><p className="text-lg font-semibold">{money.format(Number(amount))}</p></div>)}</div>{editing === "expense:new" && <ExpenseForm vehicle={vehicle} onSubmit={save} />}{expenses.length ? expenses.map((item) => editing === `expense:${item.id}` ? <ExpenseForm key={item.id} item={item} vehicle={vehicle} onSubmit={(event) => save(event, item)} /> : <Record key={item.id} title={item.category} detail={`${item.date} · ${money.format(item.amount)}`} actions={<><button onClick={() => setEditing(`expense:${item.id}`)}>Edit</button><button onClick={() => remove(item)}>Delete</button></>} />) : <Empty label="No expenses recorded." />}</Panel>; }
function Overview({ vehicle, summary, attention, overLimit, activeVehicleCount, vehicleLimit }: { vehicle: Vehicle; summary: ReturnType<typeof useGarage>["summary"]; attention: number; overLimit: boolean; activeVehicleCount: number; vehicleLimit: number | null }) { const nextMaintenance = summary?.maintenance[0]; const nextReminder = summary?.reminders.find((item) => !item.completed); return <div className="grid gap-3 md:grid-cols-2">{overLimit ? <div className="md:col-span-2 rounded-2xl border border-amber-200/20 bg-amber-200/[0.05] p-4"><p className="font-medium">You’re using {activeVehicleCount} active vehicles on Cosmic Free.</p><p className="mt-1 text-sm text-white/60">Your existing vehicle data is safe. The Free limit is {vehicleLimit}; upgrade to Cosmic+ to add or reactivate another active vehicle.</p></div> : null}<Panel title="Attention"><p className="text-3xl font-semibold">{attention}</p><p className="text-sm text-white/55">items need attention for {vehicle.nickname}</p></Panel><Panel title="Next maintenance"><p>{nextMaintenance?.name ?? "No maintenance scheduled"}</p><p className="text-sm text-white/55">{nextMaintenance ? summary?.statusById.get(nextMaintenance.id) : ""}</p></Panel><Panel title="Open issues"><p>{summary?.issues.filter((item) => item.status !== "resolved").length ?? 0} open</p></Panel><Panel title="Next reminder"><p>{nextReminder?.title ?? "No reminders"}</p></Panel><Panel title="Recent service"><p>{summary?.services[0]?.title ?? "No service history"}</p><p className="text-sm text-white/55">{summary?.services[0]?.date ?? ""}</p></Panel></div>; }
